/* English content. Same order and structure as data.js. */
const EN_T={
mt:{name:'Computers and devices',sub:'Hardware, input and output, memory',tip:'For any device question, ask yourself: is information going <b>into</b> the computer or coming <b>out</b> of it?',L:[
 ['Hardware and software','<p><b>Hardware</b> is everything you can touch: the monitor, keyboard, mouse and the computer case.</p><p><b>Software</b> is the programs that run inside, like Word or a game. You can see it on screen but you cannot touch it.</p><p>A guitar is hardware. The song is software.</p>'],
 ['Input and output devices','<p><b>Input devices</b> send information from you into the computer: keyboard, mouse, microphone, scanner, webcam.</p><p><b>Output devices</b> bring information from the computer to you: monitor, speakers, headphones, printer.</p><p>A touchscreen does both. You touch it to give orders and look at it to see the result.</p>'],
 ['The brain and the memory','<ul><li>The <b>CPU</b> is the brain. It does all the calculations.</li><li><b>RAM</b> is short-term memory. It forgets everything when the power goes off.</li><li><b>Hard drives, USB drives and memory cards</b> are long-term memory. They keep data when the power is off.</li></ul><p>That is why you must <b>save</b> your work before shutting down.</p>'],
 ['Kinds of computers','<p>A desktop computer stays in one place. A laptop folds shut and goes with you. Tablets and smartphones are small and use a touchscreen.</p>'],
 ['Measuring storage','<p>Storage size tells you how big a file is and how much a drive can hold. From small to big:</p><p><b>Byte → KB → MB → GB → TB</b></p><p>Each step is about 1000 times bigger. A photo is a few MB. A film is a few GB.</p>'],
 ['Keeping the computer healthy','<ul><li>Shut down properly: <b>Start → Power → Shut down</b>.</li><li>No food or drink near the computer. Keep hands clean and dry.</li><li>Never unplug it while it is running.</li></ul>']]},
hdh:{name:'Operating system, files and folders',sub:'Windows, the desktop, tidy files',tip:'The <b>file extension</b> (the part after the dot) tells you what kind of file it is and which program opens it.',L:[
 ['What is an operating system?','<p>The operating system is the <b>manager</b> of the computer. It controls the hardware and lets other programs run.</p><p>Computers use <b>Windows, macOS, Linux</b>. Phones and tablets use <b>Android, iOS</b>.</p>'],
 ['The Windows desktop','<ul><li>The <b>desktop</b> is the first screen you see.</li><li>An <b>icon</b> is a small picture. Double-click it to open.</li><li>The <b>taskbar</b> at the bottom shows the programs that are open.</li><li>The <b>Start button</b> opens the list of programs.</li><li>The <b>Recycle Bin</b> holds deleted files.</li></ul>'],
 ['Files and folders','<p>A <b>file</b> is like a notebook. It holds an essay, a photo or a song.</p><p>A <b>folder</b> is like a pocket in your school bag. It keeps many files tidy. A folder inside a folder is a <b>subfolder</b>.</p><p>Use clear names so files are easy to find, like <i>Essay-about-my-mum.docx</i>.</p>'],
 ['File extensions','<ul><li><b>.docx</b> Word document, <b>.txt</b> plain text, <b>.pdf</b> document for reading</li><li><b>.xlsx</b> Excel spreadsheet</li><li><b>.pptx</b> PowerPoint presentation</li><li><b>.jpg, .png</b> pictures</li><li><b>.mp3</b> sound, <b>.mp4</b> video</li></ul>'],
 ['Working with files','<ul><li><b>Rename</b>: change the name (<kbd>F2</kbd>).</li><li><b>Copy → Paste</b>: make another identical file somewhere else.</li><li><b>Cut → Paste</b>: move the file somewhere else.</li><li><b>Delete</b>: the file goes to the Recycle Bin.</li><li><b>Restore</b>: bring a file back from the Recycle Bin.</li></ul>'],
 ['The three window buttons','<p>At the top right of every window: <kbd>–</kbd> minimize to the taskbar, <kbd>□</kbd> maximize to fill the screen, <kbd>×</kbd> close the window.</p>']]},
pm:{name:'Software and everyday actions',sub:'The right program, saving, shortcuts',tip:'<kbd>Ctrl</kbd>+<kbd>C</kbd>, <kbd>V</kbd>, <kbd>X</kbd>, <kbd>Z</kbd>, <kbd>S</kbd> work the same in almost every program. Learn them once, use them everywhere.',L:[
 ['Two kinds of software','<p><b>System software</b> makes the computer work, like the Windows operating system.</p><p><b>Application software</b> helps you do one job: Word, Excel, PowerPoint, Paint, the Chrome browser.</p>'],
 ['The right program for the job','<ul><li>Letters and essays → <b>Word</b></li><li>Tables and calculations → <b>Excel</b></li><li>Presenting to the class → <b>PowerPoint</b></li><li>Drawing → <b>Paint</b></li><li>Viewing websites → a <b>browser</b> (Chrome, Edge)</li></ul>'],
 ['Save and Save As','<p><b>Save</b> (<kbd>Ctrl</kbd>+<kbd>S</kbd>) keeps your changes in the file that is open.</p><p><b>Save As</b> makes a <b>new</b> file with a different name or place. The old file stays the same.</p>'],
 ['Toolbar buttons','<p>Get to know these pictures. In the exam you often have to recognise them.</p>'],
 ['Golden shortcuts','<ul><li><kbd>Ctrl</kbd>+<kbd>C</kbd> copy, <kbd>Ctrl</kbd>+<kbd>X</kbd> cut, <kbd>Ctrl</kbd>+<kbd>V</kbd> paste</li><li><kbd>Ctrl</kbd>+<kbd>Z</kbd> undo (go back one step)</li><li><kbd>Ctrl</kbd>+<kbd>S</kbd> save, <kbd>Ctrl</kbd>+<kbd>P</kbd> print</li><li><kbd>Ctrl</kbd>+<kbd>A</kbd> select all, <kbd>Ctrl</kbd>+<kbd>O</kbd> open, <kbd>Ctrl</kbd>+<kbd>N</kbd> new file</li></ul>'],
 ['Installing and updating','<p>Only install software from places you trust, and ask an adult first. An <b>update</b> fixes bugs and makes software safer.</p><p>If a program freezes: wait a little, close and reopen it, or restart the computer.</p>']]},
vb:{name:'Word processing',sub:'Word: typing, formatting, pictures, printing',tip:'To change how text looks, <b>select</b> the text first, then click the formatting button.',L:[
 ['Typing and fixing text','<ul><li><kbd>Enter</kbd> starts a new line or paragraph.</li><li><kbd>Space</kbd> puts a gap between two words.</li><li><kbd>Backspace</kbd> deletes the character to the <b>left</b> of the cursor.</li><li><kbd>Delete</kbd> deletes the character to the <b>right</b> of the cursor.</li><li><kbd>Caps Lock</kbd> turns capital letters on or off.</li></ul>'],
 ['Formatting text','<ul><li><b>B</b> (Bold): <kbd>Ctrl</kbd>+<kbd>B</kbd></li><li><i>I</i> (Italic): <kbd>Ctrl</kbd>+<kbd>I</kbd></li><li><u>U</u> (Underline): <kbd>Ctrl</kbd>+<kbd>U</kbd></li><li>You can also change the font, the size and the colour.</li></ul>'],
 ['Aligning paragraphs','<ul><li>Align left: <kbd>Ctrl</kbd>+<kbd>L</kbd></li><li>Center: <kbd>Ctrl</kbd>+<kbd>E</kbd> (good for titles)</li><li>Align right: <kbd>Ctrl</kbd>+<kbd>R</kbd></li><li>Justify: <kbd>Ctrl</kbd>+<kbd>J</kbd></li></ul>'],
 ['Adding pictures and tables','<p>Everything you add to the page is on the <b>Insert</b> tab: <b>Pictures</b>, <b>Table</b>, <b>Shapes</b>.</p>'],
 ['Spelling and finding','<p>A <b>red wavy line</b> under a word means it may be misspelled.</p><p><kbd>Ctrl</kbd>+<kbd>F</kbd> finds a word. <kbd>Ctrl</kbd>+<kbd>H</kbd> finds a word and replaces it with another.</p>'],
 ['Printing','<p>Press <kbd>Ctrl</kbd>+<kbd>P</kbd> to print. Check the print preview first.</p><p>An upright page is <b>Portrait</b>. A sideways page is <b>Landscape</b>.</p>']]},
bt:{name:'Spreadsheets',sub:'Excel: cells, formulas, functions, charts',tip:'A cell address is always <b>column first, row second</b>. A formula always starts with <kbd>=</kbd>.',L:[
 ['Rows, columns and cells','<p><b>Columns</b> go down and are named with letters A, B, C. <b>Rows</b> go across and are numbered 1, 2, 3.</p><p>A <b>cell</b> is where a column meets a row. The cell in column B, row 3 is <b>B3</b>.</p>'],
 ['Entering data','<p>Click a cell and type words or numbers. Press <kbd>Enter</kbd> to go down one cell, <kbd>Tab</kbd> to go right.</p>'],
 ['Formulas','<p>A formula always starts with <b>=</b>. For example <b>=A1+B1</b> adds cells A1 and B1.</p><p>Signs: add <kbd>+</kbd>, subtract <kbd>-</kbd>, multiply <kbd>*</kbd>, divide <kbd>/</kbd>. Excel multiplies and divides before it adds and subtracts, just like in maths.</p>'],
 ['Useful functions','<ul><li><b>=SUM(A1:A5)</b> adds up</li><li><b>=AVERAGE(A1:A5)</b> finds the average</li><li><b>=MAX(A1:A5)</b> finds the biggest number</li><li><b>=MIN(A1:A5)</b> finds the smallest number</li><li><b>=COUNT(A1:A5)</b> counts cells with numbers</li></ul><p><b>A1:A5</b> means the cells from A1 to A5. That is 5 cells.</p>'],
 ['Sort and filter','<p><b>Sort</b> puts data in order, like names from A to Z or scores from high to low.</p><p><b>Filter</b> shows only the rows you want to see.</p>'],
 ['Charts','<ul><li><b>Column chart</b>: compares numbers.</li><li><b>Pie chart</b>: shows each part of a whole.</li><li><b>Line chart</b>: shows change over time.</li></ul>']]},
tc:{name:'Presentations',sub:'PowerPoint: slides, effects, presenting',tip:'A <b>transition</b> happens <b>between two slides</b>. An <b>animation</b> happens to <b>text or pictures inside</b> one slide.',L:[
 ['What is a slide?','<p>PowerPoint is for making presentations. Each page is a <b>slide</b>.</p><p>The first one is the <b>title slide</b>, with the title and the presenter’s name.</p>'],
 ['Adding slides and layouts','<p>Click <b>New Slide</b> (or <kbd>Ctrl</kbd>+<kbd>M</kbd>) to add a slide.</p><p>The <b>layout</b> decides where the title, text and pictures go.</p>'],
 ['Adding pictures','<p>Like in Word, use the <b>Insert</b> tab for <b>Pictures</b>, <b>Shapes</b> and <b>Table</b>. Pictures help people understand faster.</p>'],
 ['Two kinds of effects','<p><b>Transition</b>: how one slide changes to the next, like turning a page.</p><p><b>Animation</b>: how a line of text or a picture appears inside a slide, like flying in from the left.</p>'],
 ['Presenting','<ul><li><kbd>F5</kbd> starts from the first slide</li><li><kbd>Shift</kbd>+<kbd>F5</kbd> starts from the current slide</li><li>Arrow keys, Space or a click go to the next slide</li><li><kbd>Esc</kbd> leaves the show</li></ul>'],
 ['Good-looking slides','<ul><li>Few words, big text that can be read from the back of the room.</li><li>Text colour that stands out from the background.</li><li>Clear pictures.</li><li>Look at your audience and use your own words.</li></ul>']]},
net:{name:'Internet and searching',sub:'Browsers, web addresses, can I trust it?',tip:'Before you believe something online, ask three questions: <b>Who wrote it? When? Do other places say the same?</b>',L:[
 ['The Internet and websites','<p>The <b>Internet</b> is a network joining billions of computers around the world. <b>Websites</b> hold information on the Internet.</p><p><b>Wi-Fi</b> connects a device to the network without cables.</p>'],
 ['Browsers','<p>A browser is the program for viewing websites: <b>Chrome, Edge, Firefox, Safari</b>.</p><ul><li><b>Back</b> returns to the previous page, <b>Forward</b> goes ahead</li><li><b>Refresh</b> (<kbd>F5</kbd>) reloads the page</li><li><b>Tabs</b> open many pages in one window</li><li><b>Bookmarks</b> (Favorites) save pages you like</li></ul>'],
 ['Web addresses','<p>Every web page has an address called a <b>URL</b>, like <i>https://www.moet.gov.vn</i>.</p><ul><li><b>https</b> and a padlock: the connection is secure.</li><li><b>.vn</b> Vietnam, <b>.edu</b> education, <b>.gov</b> government, <b>.com</b> business, <b>.org</b> organization.</li></ul>'],
 ['Searching well','<p>A <b>search engine</b> like Google or Bing helps you find information.</p><p>Use short <b>keywords</b> that say exactly what you need. Put a phrase in <b>“quotation marks”</b> to find that exact phrase.</p>'],
 ['Links, downloads, uploads','<p>A <b>hyperlink</b> is text or a picture that opens another page when you click it. The mouse pointer turns into a hand.</p><p><b>Download</b> brings a file from the Internet to your computer. <b>Upload</b> sends a file from your computer to the Internet.</p>'],
 ['Can I trust this?','<ul><li>Who wrote it? Do they know the subject?</li><li>When was it written? Is it still new?</li><li>Do other sites say the same thing?</li></ul><p>Sites from schools, governments and well-known newspapers are usually more reliable.</p>']]},
gt:{name:'Email and communication',sub:'Email, video calls, teamwork',tip:'<b>Reply</b> answers the sender. <b>Reply All</b> answers everyone in the message. <b>Forward</b> sends the message on to someone else.',L:[
 ['Email addresses','<p>An email address looks like <b>name@provider</b>, for example <i>may.nguyen@gmail.com</i>.</p><p>The <b>@</b> sign is read “at”. An email address has no spaces.</p>'],
 ['Parts of an email','<ul><li><b>To</b>: the receiver</li><li><b>Cc</b>: a copy for someone else to see</li><li><b>Bcc</b>: a copy that other receivers cannot see</li><li><b>Subject</b>: the title</li><li><b>Attach</b> (paperclip): add a file</li></ul>'],
 ['Mail folders','<ul><li><b>Inbox</b>: messages you received</li><li><b>Sent</b>: messages you sent</li><li><b>Drafts</b>: unfinished messages</li><li><b>Spam / Junk</b>: junk mail</li><li><b>Trash</b>: deleted messages</li></ul>'],
 ['Writing politely','<ul><li>Give it a clear subject.</li><li>Start with a greeting. End with thanks and your name.</li><li>Do not WRITE ALL IN CAPITALS. It looks like shouting.</li><li>Read it again before you click <b>Send</b>.</li></ul>'],
 ['Many ways to talk','<p>Email suits long messages and files. <b>Text messages</b> (SMS) and <b>instant messages</b> suit quick questions. <b>Video calls</b> (Zoom, Google Meet, Teams) suit online lessons and meetings.</p>'],
 ['Working as a team','<p>With an online document like <b>Google Docs</b>, the whole group can edit at the same time. Cloud storage like <b>Google Drive</b> or <b>OneDrive</b> lets you share files.</p><p>Respect your teammates’ ideas, and ask before you delete someone’s part.</p>']]},
at:{name:'Safety and digital citizenship',sub:'Passwords, scams, copyright, kindness',tip:'If something online feels strange or worrying, the right answer is almost always: <b>do not do it, and tell your parents or teacher</b>.',L:[
 ['Personal information','<p>Your full name, home address, phone number, school, passwords and photos are <b>personal information</b>.</p><p>Do not share them with strangers online.</p>'],
 ['Strong passwords','<ul><li>At least 8 characters.</li><li>Capital letters, small letters, numbers and symbols.</li><li>Not your name, your birthday or 123456.</li><li>Only you and your parents know it. <b>Sign out</b> when you finish on a shared computer.</li></ul>'],
 ['Viruses and scams','<p>A <b>virus</b> is bad software that harms the computer or steals information. <b>Antivirus software</b> finds and removes it.</p><p>A <b>scam</b> is often a message saying “you won a prize”, rushing you, or asking for a password. Do not click strange links or open attachments from strangers.</p>'],
 ['Cyberbullying','<p>If someone is mean to you online: <b>do not reply</b>, <b>take a screenshot</b> as proof, <b>block</b> them and <b>tell an adult</b>.</p><p>Only write things you would say to a friend’s face.</p>'],
 ['Copyright','<p>Writing, photos, music and software all belong to someone. <b>Ask permission</b> or <b>say where it came from</b>.</p><p>Copying someone’s work and saying it is yours is <b>plagiarism</b>. Using illegally copied software breaks copyright.</p>'],
 ['Digital footprint and health','<p>Everything you post leaves a <b>digital footprint</b> that can stay for a very long time. Think before you post.</p><p>Sit up straight with your eyes about 50 to 70 cm from the screen. About every 20 minutes, rest your eyes by looking far away.</p>']]}
};

